System.register("chunks:///_virtual/manifest2.ts",["cc"],(function(e){var a;return{setters:[function(e){a=e.cclegacy}],execute:function(){a._RF.push({},"69e01JV8LFJU5e23u6qg5KH","manifest",void 0);e("MANIFEST",{manifest_version:1,game_id:"sg-reaction-time-test",slug:"reaction-time-test",name:{it:"Test dei riflessi",en:"Reaction Time Test"},description:{it:"Aspetta il verde e tocca più in fretta che puoi. Cinque tentativi, un tempo in millisecondi.",en:"Wait for green, then tap as fast as you can. Five tries, one time in milliseconds."},genre:"reaction",template_id:"reflex",engine:"cocos-3.8.8",version:"1.0.0",orientation:"portrait",game_rules:{variant:"reaction_test",attempts:5,delay_min_ms:1500,delay_max_ms:5e3,min_reaction_ms:100,max_reaction_ms:2e3,modes:[{id:"classic",target_radius:null,verdict_ms:[200,260,330]},{id:"target",target_radius:135,verdict_ms:[380,470,600]}]},scoring_rules:{score_k:1e5,max_points:1e3,false_start_penalty:25},supported_platforms:["web","telegram"],supported_locales:["it","en"],default_locale:"en",target_countries:["*"],age_rating:"PEGI 3",privacy_profile:{personal_data:!1,analytics:"pseudonymous_install",account_required:!1},monetization_profile:{rewarded_ads:!1,interstitial_ads:!1,iap:!0},social_profile:{share:!0,leaderboard:!0,challenge:!0},analytics_profile:{sink:"memory",flush_interval_ms:5e3},difficulty_config:{level:"normal"},asset_manifest:{theme:"settegames",palette:{background:"#FF2D8B",primary:"#3B82FF",accent:"#FFC83D",text:"#1A0B4B",muted:"#F4F6FF"},sounds:"synth",provenance:"Colori dal brand kit SetteGames (rosa #FF2D8B come campo d'attesa, blu, giallo, viola-scuro, bianco-lavanda) più un verde segnale #2EE86F per il via; caratteri Titan One e Baloo 2 (OFL, da Scopa, come Perfect Timer); suoni sintetizzati dal codice; forme e icone disegnate dal codice. Nessun asset di terzi. Direzione: .impeccable.md"},build_config:{targets:["web-mobile"],max_gzip_kb:1200},release_config:{channels:["web","telegram"],status:"draft"},legal_status:{original_concept:!0,trademark_check:"pending",gambling_mechanics:!1,notes:"Il test del tempo di reazione è un esercizio generico (stimolo visivo → tocco), usato da decenni in psicologia e nei giochi. Design, grafica, testi e regole sono nostri; nessun marchio, nome, colore o testo di siti terzi (in particolare nessun riferimento a Human Benchmark). Nome e parole chiave sono descrizioni generiche del genere. Le fasce dei verdetti sono fisse e dichiarate come tali, senza percentili inventati."},experiment_config:{active:[]},seo:{keywords:["reaction time test","reaction test","reflex test","test your reaction time","reaction speed test","reaction time game"],headline:{en:"Reaction Time Test – Test Your Reflexes",it:"Test dei riflessi – Misura la tua reazione"},long_description:{en:"Reaction Time Test is a free online reflex test. The screen waits on pink, then turns green at a random moment: tap as fast as you can. Five attempts give you an average in milliseconds, with your best attempt and a plain verdict. Tapping too early counts as a false start. Target mode adds aim: a circle pops up somewhere on the screen and you have to hit it.",it:"Test dei riflessi è un test del tempo di reazione gratis online. Lo schermo aspetta sul rosa, poi diventa verde in un momento a caso: tocca più in fretta che puoi. Cinque tentativi ti danno una media in millisecondi, con il tentativo migliore e un verdetto semplice. Toccare troppo presto è una partenza falsa. La modalità Bersaglio aggiunge la mira: un cerchio compare in un punto dello schermo e devi colpirlo."},how_to_play:{en:["Tap PLAY, then tap once to start the first attempt.","The screen turns pink and says “Wait for green”. Keep your finger ready, but do not tap yet.","At a random moment the screen turns green and the shape changes to a big circle: tap as fast as you can.","Your time appears in milliseconds. Tapping before green is a false start: it costs points and the attempt is repeated.","After five attempts you get your average, your best attempt and your score. In Target mode, tap the circle that pops up instead."],it:["Tocca GIOCA, poi tocca una volta per iniziare il primo tentativo.","Lo schermo diventa rosa e dice «Aspetta il verde». Tieni il dito pronto, ma non toccare ancora.","In un momento a caso lo schermo diventa verde e la forma cambia in un grande cerchio: tocca più in fretta che puoi.","Il tuo tempo compare in millisecondi. Toccare prima del verde è una partenza falsa: costa punti e il tentativo si ripete.","Dopo cinque tentativi vedi la media, il tentativo migliore e il punteggio. In modalità Bersaglio, tocca invece il cerchio che compare."]},faq:[{q:{en:"What is a good reaction time?",it:"Qual è un buon tempo di reazione?"},a:{en:"For a simple visual signal, most people land somewhere around 200–300 ms on a touch screen, and many land a bit higher. Under 200 ms is very quick. Times change with age, focus, tiredness and the device, so compare yourself with yourself.",it:"Con un segnale visivo semplice, la maggior parte delle persone sta intorno ai 200–300 ms su uno schermo touch, e molte un po' sopra. Sotto i 200 ms è molto veloce. I tempi cambiano con età, attenzione, stanchezza e dispositivo: confrontati con te stesso."}},{q:{en:"Why is my time different on another device?",it:"Perché il mio tempo cambia su un altro dispositivo?"},a:{en:"Every screen and touch panel adds its own delay: display refresh rate, touch sampling and browser processing can add from a few to several tens of milliseconds. The game measures from the frame where green is drawn to the moment your tap reaches the page, so it cannot remove the latency of your hardware. Use the same device to track your progress.",it:"Ogni schermo e pannello touch aggiunge il suo ritardo: frequenza del display, campionamento del tocco ed elaborazione del browser possono aggiungere da pochi a diverse decine di millisecondi. Il gioco misura dal fotogramma in cui il verde viene disegnato al momento in cui il tocco arriva alla pagina, quindi non può togliere la latenza del tuo hardware. Usa lo stesso dispositivo per seguire i tuoi progressi."}},{q:{en:"What happens if I tap too soon?",it:"Cosa succede se tocco troppo presto?"},a:{en:"Tapping before green is a false start: the screen says “Too soon!”, you lose a few points and the same attempt starts again with a new random wait. A tap less than 100 ms after green also counts as a false start, because nobody reacts that fast: it is a guess.",it:"Toccare prima del verde è una partenza falsa: lo schermo dice «Troppo presto!», perdi qualche punto e lo stesso tentativo riparte con una nuova attesa a caso. Anche un tocco meno di 100 ms dopo il verde conta come partenza falsa, perché nessuno reagisce così in fretta: è un tentativo a indovinare."}},{q:{en:"How is the score calculated?",it:"Come si calcola il punteggio?"},a:{en:"Your score is 100,000 divided by your average time in milliseconds, minus 25 points for each false start. An average of 250 ms gives 400 points. The weekly leaderboard uses this score.",it:"Il punteggio è 100.000 diviso la tua media in millisecondi, meno 25 punti per ogni partenza falsa. Una media di 250 ms vale 400 punti. La classifica settimanale usa questo punteggio."}},{q:{en:"What is Target mode?",it:"Cos'è la modalità Bersaglio?"},a:{en:"Instead of the whole screen turning green, a circle pops up at a random spot and you must tap inside it. It tests reaction and aim together, so times are naturally slower than in Classic.",it:"Invece di tutto lo schermo che diventa verde, compare un cerchio in un punto a caso e devi toccarlo dentro. Mette alla prova reazione e mira insieme, quindi i tempi sono naturalmente più lenti che in Classica."}},{q:{en:"Can I challenge my friends?",it:"Posso sfidare i miei amici?"},a:{en:"Yes. At the end of a game tap Challenge a friend to send a link with your score; your friend opens it and tries to beat you.",it:"Sì. A fine partita tocca Sfida un amico per mandare un link con il tuo punteggio: il tuo amico lo apre e prova a batterti."}}]}}),e("BUILD_INFO",{hash:"369cb14fbcf5a6d1",hubUrl:"https://jvmpwhoosojharlbmgsi.supabase.co/functions/v1/hub-api"});a._RF.pop()}}}));

